mapper.select:
select , null as subject_name
from drive_personal_quota_policy p
where p.subject_type = #{subjectType}
  and p.subject_id = #{subjectId}

mapper.insert:
insert into drive_personal_quota_policy (
    subject_type, subject_id, quota_bytes, priority, expire_time,
    status, version, create_by, create_time, update_by, update_time, remark
) values (
    #{subjectType}, #{subjectId}, #{quotaBytes}, #{priority}, #{expireTime},
    #{status}, #{version}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{remark}
)

mapper.update:
update drive_personal_quota_policy
set quota_bytes = #{quotaBytes},
    priority = #{priority},
    expire_time = #{expireTime},
    status = #{status},
    version = version + 1,
    update_by = #{updateBy},
    update_time = #{updateTime},
    remark = #{remark}
where subject_type = #{subjectType}
  and subject_id = #{subjectId}
  and version = #{version}

mapper.delete:
delete from drive_personal_quota_policy
where subject_type = #{subjectType}
  and subject_id = #{subjectId}
  and version = #{version}
  and subject_type <> 'GLOBAL'
